mapper.update:
UPDATE plt_authorization_grant
SET status_code = 'EXPIRED', current_marker = NULL, version = version + 1,
    update_time = #{query.expiredAt}
WHERE tenant_id = #{query.tenantId}
  AND subject_type_code = #{query.subjectTypeCode}
  AND subject_id = #{query.subjectId}
  AND resource_context_code = #{query.resourceContextCode}
  AND resource_type_code = #{query.resourceTypeCode}
  AND resource_id = #{query.resourceId}
  AND action_code = #{query.actionCode}
  AND scope_code = #{query.scopeCode}
  AND status_code = 'ACTIVE'
  AND current_marker = 1
  AND effective_to IS NOT NULL
  AND effective_to <= #{query.expiredAt}
  AND deleted = b'0'

UPDATE plt_authorization_grant
SET status_code = 'REVOKED', current_marker = NULL,
    revoked_by = #{update.revokedBy}, revoked_at = #{update.revokedAt},
    revoke_reason = #{update.revokeReason}, version = version + 1,
    update_time = #{update.revokedAt}
WHERE tenant_id = #{update.tenantId}
  AND id = #{update.grantId}
  AND version = #{update.expectedVersion}
  AND status_code = 'ACTIVE'
  AND current_marker = 1
  AND deleted = b'0'
